/* Phase T21: FiberBlock */
#ifdef __clang__
#pragma clang diagnostic push
#pragma clang diagnostic ignored "-Wdeprecated-declarations"
#endif
typedef struct FiberBlock FiberBlock;
struct FiberBlock {
    ucontext_t ctx;
    ucontext_t caller_ctx;
    char *stack;
    size_t stack_size;
    int done;
    int parked; /* Phase T21: scheduler park/unpark */
    int64_t result;
    int64_t arg;
    void *effect_handler_chain; /* Phase P19-8: per-fiber effect handler chain */
    void (*entry_fn)(void);
    void *fiber_local; /* Phase T21: fiber-local storage */
    void *task_group; /* Parent TaskGroup for cancellation */
    bool cancelled; /* Set when parent TaskGroup is cancelled */
};

static __thread FiberBlock *tur_current_fiber = NULL;
static __thread bool tur_fiber_cancelled_flag = false;

static void tur_task_group_notify_done(void *task_group);

static void tur_fiber_shim(uint32_t hi, uint32_t lo) {
    FiberBlock *f = (FiberBlock *)(((uintptr_t)hi << 32) | (uintptr_t)(uint32_t)lo);
    f->entry_fn();
    f->done = 1;
    tur_task_group_notify_done(f->task_group);
    swapcontext(&f->ctx, &f->caller_ctx);
    abort();
}

static FiberBlock *tur_fiber_block_new(void (*fn)(void), size_t stack_size) {
    if (!stack_size) stack_size = 1024 * 1024;
    FiberBlock *f = (FiberBlock *)calloc(1, sizeof(FiberBlock));
    if (!f) { fprintf(stderr, "fiber: oom\n"); abort(); }
    f->stack = (char *)malloc(stack_size);
    if (!f->stack) { free(f); abort(); }
    f->stack_size = stack_size; f->entry_fn = fn; f->done = 0;
    getcontext(&f->ctx);
    f->ctx.uc_stack.ss_sp = f->stack;
    f->ctx.uc_stack.ss_size = stack_size;
    f->ctx.uc_link = NULL;
    uintptr_t _fp = (uintptr_t)f;
    uint32_t _hi = (uint32_t)(_fp >> 32);
    uint32_t _lo = (uint32_t)(_fp & 0xFFFFFFFFU);
    makecontext(&f->ctx, (void(*)(void))tur_fiber_shim, 2, _hi, _lo);
    return f;
}

static int64_t tur_fiber_block_resume(FiberBlock *f, int64_t arg) {
    if (!f || f->done) return f ? f->result : 0;
    if (f->cancelled) { f->done = 1; return 0; }
    if (f->task_group) {
        typedef struct TaskGroupBlock { bool cancelled; } TaskGroupBlock;
        if (((TaskGroupBlock *)f->task_group)->cancelled) { f->cancelled = 1; f->done = 1; return 0; }
    }
    FiberBlock *_prev = tur_current_fiber;
    tur_current_fiber = f;
    f->arg = arg;
    swapcontext(&f->caller_ctx, &f->ctx);
    tur_current_fiber = _prev;
    return f->result;
}

static void tur_fiber_block_yield(int64_t value) {
    FiberBlock *f = tur_current_fiber;
    if (!f) { fprintf(stderr, "fiber-yield: not in fiber\n"); abort(); }
    f->result = value;
    swapcontext(&f->ctx, &f->caller_ctx);
}

typedef struct FiberLocalEntry FiberLocalEntry;
struct FiberLocalEntry {
    int64_t key;
    int64_t value;
    FiberLocalEntry *next;
};

static void tur_fiber_local_free(FiberBlock *f) {
    FiberLocalEntry *e = (FiberLocalEntry *)f->fiber_local;
    while (e) { FiberLocalEntry *n = e->next; free(e); e = n; }
}

static int64_t tur_fiber_local_get(FiberBlock *f, int64_t key) {
    FiberLocalEntry *e = (FiberLocalEntry *)f->fiber_local;
    while (e) { if (e->key == key) return e->value; e = e->next; }
    return 0;
}

static void tur_fiber_local_set(FiberBlock *f, int64_t key, int64_t value) {
    FiberLocalEntry *e = (FiberLocalEntry *)f->fiber_local;
    while (e) { if (e->key == key) { e->value = value; return; } e = e->next; }
    FiberLocalEntry *n = (FiberLocalEntry *)malloc(sizeof(FiberLocalEntry));
    if (!n) { fprintf(stderr, "fiber-local: oom\n"); abort(); }
    n->key = key; n->value = value;
    n->next = (FiberLocalEntry *)f->fiber_local;
    f->fiber_local = (void *)n;
}

static void tur_fiber_block_free(FiberBlock *f) {
    if (!f) return;
    tur_fiber_local_free(f);
    free(f->stack); free(f);
}

static bool tur_fiber_cancelled(void) {
    return tur_fiber_cancelled_flag;
}

static void tur_fiber_set_cancelled(bool c) {
    tur_fiber_cancelled_flag = c;
}

static void tur_task_group_notify_done(void *task_group) {
    if (!task_group) return;
    typedef struct TaskGroupBlock {
        pthread_mutex_t lock;
        pthread_cond_t done_cond;
        int64_t task_count;
        int64_t completed_count;
        bool cancelled;
        bool done;
        pthread_t owner_thread;
    } TaskGroupBlock;
    TaskGroupBlock *g = (TaskGroupBlock *)task_group;
    pthread_mutex_lock(&g->lock);
    g->completed_count++;
    if (g->completed_count >= g->task_count) {
        g->done = true;
        pthread_cond_broadcast(&g->done_cond);
    }
    pthread_mutex_unlock(&g->lock);
}

typedef struct TurScheduler TurScheduler;
struct TurScheduler {
    FiberBlock **run_queue;
    int64_t run_queue_cap;
    int64_t run_queue_len;
    int64_t run_queue_head;
    int64_t run_queue_tail;
    FiberBlock *current_fiber;
    bool running;
};

static TurScheduler *tur_scheduler = NULL;

static TurScheduler *tur_scheduler_new(void) {
    TurScheduler *s = (TurScheduler *)calloc(1, sizeof(TurScheduler));
    if (!s) { fprintf(stderr, "scheduler: oom\n"); abort(); }
    s->run_queue_cap = 64;
    s->run_queue = (FiberBlock **)malloc(sizeof(FiberBlock *) * (size_t)s->run_queue_cap);
    if (!s->run_queue) { free(s); fprintf(stderr, "scheduler: queue oom\n"); abort(); }
    s->run_queue_len = 0;
    s->run_queue_head = 0;
    s->run_queue_tail = 0;
    s->current_fiber = NULL;
    s->running = false;
    return s;
}

static TurScheduler *tur_scheduler_current(void) {
    return tur_scheduler;
}

static void tur_scheduler_enqueue(TurScheduler *s, FiberBlock *f) {
    if (s->run_queue_len >= s->run_queue_cap) {
        int64_t new_cap = s->run_queue_cap * 2;
        FiberBlock **new_q = (FiberBlock **)malloc(sizeof(FiberBlock *) * (size_t)new_cap);
        if (!new_q) { fprintf(stderr, "scheduler: grow oom\n"); abort(); }
        for (int64_t i = 0; i < s->run_queue_len; i++)
            new_q[i] = s->run_queue[(s->run_queue_head + i) % s->run_queue_cap];
        free(s->run_queue);
        s->run_queue = new_q;
        s->run_queue_cap = new_cap;
        s->run_queue_head = 0;
        s->run_queue_tail = s->run_queue_len;
    }
    s->run_queue[s->run_queue_tail] = f;
    s->run_queue_tail = (s->run_queue_tail + 1) % s->run_queue_cap;
    s->run_queue_len++;
}

static FiberBlock *tur_scheduler_dequeue(TurScheduler *s) {
    if (s->run_queue_len == 0) return NULL;
    FiberBlock *f = s->run_queue[s->run_queue_head];
    s->run_queue_head = (s->run_queue_head + 1) % s->run_queue_cap;
    s->run_queue_len--;
    return f;
}

static void tur_scheduler_spawn(TurScheduler *s, FiberBlock *f) {
    tur_scheduler_enqueue(s, f);
}

static void tur_scheduler_run(TurScheduler *s) {
    s->running = true;
    while (s->running) {
        FiberBlock *f = tur_scheduler_dequeue(s);
        if (!f) { break; }
        s->current_fiber = f;
        tur_fiber_block_resume(f, 0);
        s->current_fiber = NULL;
        if (!f->done && !f->parked) tur_scheduler_enqueue(s, f);
    }
    s->running = false;
}

static void tur_scheduler_run_to_completion(TurScheduler *s) {
    s->running = true;
    while (s->run_queue_len > 0 && s->running) {
        FiberBlock *f = tur_scheduler_dequeue(s);
        if (f) {
            s->current_fiber = f;
            tur_fiber_block_resume(f, 0);
            s->current_fiber = NULL;
            if (!f->done && !f->parked) tur_scheduler_enqueue(s, f);
        }
    }
    s->running = false;
}

static void tur_scheduler_yield(void) {
    tur_fiber_block_yield(0);
}

static void tur_scheduler_park(void) {
    if (tur_current_fiber) tur_current_fiber->parked = 1;
    tur_fiber_block_yield(0);
}

static void tur_scheduler_unpark(FiberBlock *f) {
    if (!f) return;
    f->parked = 0;
    if (tur_scheduler) tur_scheduler_enqueue(tur_scheduler, f);
}

typedef struct TurTimeout TurTimeout;
struct TurTimeout {
    int64_t ms;
    void (*callback)(void *arg);
    void *arg;
    pthread_t thread;
    TurTimeout *next;
};

static TurTimeout *tur_timeout_list = NULL;
static pthread_mutex_t tur_timeout_lock = PTHREAD_MUTEX_INITIALIZER;

static void *tur_timeout_thread(void *raw) {
    TurTimeout *t = (TurTimeout *)raw;
    if (t->ms > 0) {
        struct timespec ts;
        ts.tv_sec = t->ms / 1000;
        ts.tv_nsec = (t->ms % 1000) * 1000000L;
        nanosleep(&ts, NULL);
    }
    t->callback(t->arg);
    pthread_mutex_lock(&tur_timeout_lock);
    TurTimeout *prev = NULL;
    TurTimeout *curr = tur_timeout_list;
    while (curr && curr != t) { prev = curr; curr = curr->next; }
    if (prev) prev->next = t->next;
    else tur_timeout_list = t->next;
    pthread_mutex_unlock(&tur_timeout_lock);
    free(t);
    return NULL;
}

static void tur_scheduler_timeout(int64_t ms, void (*callback)(void *arg), void *arg) {
    TurTimeout *t = (TurTimeout *)malloc(sizeof(TurTimeout));
    if (!t) { fprintf(stderr, "timeout: oom\n"); abort(); }
    t->ms = ms;
    t->callback = callback;
    t->arg = arg;
    t->next = NULL;
    pthread_mutex_lock(&tur_timeout_lock);
    t->next = tur_timeout_list;
    tur_timeout_list = t;
    pthread_mutex_unlock(&tur_timeout_lock);
    pthread_attr_t attr;
    pthread_attr_init(&attr);
    pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_DETACHED);
    pthread_t tid;
    pthread_create(&tid, &attr, tur_timeout_thread, t);
    pthread_attr_destroy(&attr);
}

